function importText(t,source=""){if(t.length>10000000)throw Error('Lista demasiado grande');let name='',logo='',epg='',group='',radio=false,added=0,found=0,duplicates=0,blocked=0,invalid=0;const known=new Set(channels.map(c=>c[2]));for(const l of t.split(/\r?\n/)){const s=l.trim();if(s.startsWith('#EXTINF:')){if(name)invalid++;found++;const match=s.match(/,(?=[^"]*$)/);name=match?s.slice(match.index+1).trim():'';radio=/radio\s*=\s*"true"/i.test(s);logo=s.match(/tvg-logo="([^"]*)"/i)?.[1]||"";epg=s.match(/tvg-id="([^"]*)"/i)?.[1]||"";group=s.match(/group-title="([^"]*)"/i)?.[1]||"";radio=radio||/\b(radio|radios|audio)\b/i.test(group)}else if(s&&!s.startsWith('#')&&name){if(restricted(name)||youtubeUrl(s))blocked++;else if(!/^https:\/\//i.test(s)||added>=20000)invalid++;else if(known.has(s)){duplicates++;const old=channels.find(c=>c[2]===s);if(old){old[3]||=epg;old[4]||=logo;old[5]||=group;old[6]=country123([name,old[1],s,epg,logo,group,old[6]],source);}}else{channels.push([name,(radio||/\.(mp3|aac|ogg|opus|flac|m4a)(?:[?#]|$)/i.test(s))?'Radio':'TV',s,epg,logo,group,country123([name,"TV",s,epg,logo,group],source)]);known.add(s);added++}name='';}}invalid=found-added-duplicates-blocked;localStorage.setItem('iptv',JSON.stringify(channels.filter(c=>!baseUrls.has(c[2])&&!vodMeta[c[2]])));render();$('importReport').textContent=`Encontradas: ${found} · Nuevas: ${added} · Duplicadas: ${duplicates} · Restringidas: ${blocked} · Inválidas o no HTTPS: ${invalid}. Disponibilidad no verificada.`}
