async function refreshTdt(){const results=[];for(const kind of ['tv','radio']){try{const r=await fetch(`${tdtBase}/lists/${kind}.json`);if(!r.ok)throw Error('HTTP '+r.status);const j=await r.json();const known=new Set(channels.map(c=>c[2]));let n=0;for(const country of j.countries||[])for(const group of country.ambits||[])for(const c of group.channels||[]){if(restricted(c.name)||(c.extra_info||[]).some(x=>['GEO','NOEM','EXTA'].includes(x)))continue;for(const o of (c.options||[]).filter(o=>/^https:\/\//i.test(o.url)&&o.geo2==null&&!o.url.includes('[')&&['m3u8','mp3','aac','ogg','opus','flac','mp4','m3u','stream'].includes(o.format))){if(!o||youtubeUrl(o.url))continue;if(known.has(o.url)){const old=channels.find(x=>x[2]===o.url);if(old&&!isVod(old)&&old[0]!=='RMRC Radio'){old[3]=c.epg_id||'';old[4]=c.logo||'';old[1]=kind==='radio'?'Radio':'TV';old[6]=country.name==='Spain'?'España':country.name;}continue;}channels.push([c.name,kind==='radio'?'Radio':'TV',o.url,c.epg_id||'',c.logo||'',group.name||'',country.name==='Spain'?'España':country.name]);known.add(o.url);n++;}}results.push(`${kind}: ${n} nuevas`);}catch(e){results.push(`${kind}: ${e.message} (posible CORS)`);}}try{localStorage.setItem('iptv',JSON.stringify(channels.filter(c=>!baseUrls.has(c[2])&&!vodMeta[c[2]])));}catch{}render();$('importReport').textContent=results.join(' · ');}
