guideButton.onclick=async()=>{const c=selected;if(!c||c[1]!=='TV'){ $('status').textContent='Selecciona un canal de televisión.';return;}try{if(!guideCache||Date.now()-guideTime>21600000){const r=await fetch(tdtBase+'/epg/TV.xml.gz');if(!r.ok)throw Error('HTTP '+r.status);const bytes=await r.arrayBuffer();const a=new Uint8Array(bytes);let text;if(a[0]===31&&a[1]===139){if(!window.DecompressionStream)throw Error('Este navegador no admite GZIP');text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();}else{text=new TextDecoder().decode(bytes);}guideCache=new DOMParser().parseFromString(text,'application/xml');guideTime=Date.now();}const ids=new Set([c[3],c[0]]);for(const ch of guideCache.querySelectorAll('channel'))if([...ch.querySelectorAll('display-name')].some(n=>n.textContent.trim().toLowerCase()===c[0].trim().toLowerCase()))ids.add(ch.getAttribute('id'));const programs=[...guideCache.querySelectorAll('programme')].filter(p=>ids.has(p.getAttribute('channel'))&&xmlDate(p.getAttribute('stop'))>Date.now()).sort((a,b)=>xmlDate(a.getAttribute('start'))-xmlDate(b.getAttribute('start'))).slice(0,30);const d=document.createElement('dialog');const title=document.createElement('h2');title.textContent='Programación · '+c[0];d.append(title);for(const p of programs){const line=document.createElement('p');line.textContent=new Date(xmlDate(p.getAttribute('start'))).toLocaleString()+' · '+(p.querySelector('title')?.textContent||'Sin título');d.append(line);}if(!programs.length)d.append('Sin coincidencias en la guía.');const close=document.createElement('button');close.textContent='Cerrar';close.onclick=()=>d.close();d.append(close);d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();}catch(e){$('status').textContent='No se pudo cargar la guía: '+e.message;}};

let browseOpen=true;function setBrowse(open){if(!open&&browseOpen)catalogOffset=$('list').scrollTop;browseOpen=open;document.body.classList.toggle('browse-hidden',!open);$('browse').title=open?'Ocultar catálogo':'Mostrar catálogo';$('browse').setAttribute('aria-label',$('browse').title);if(open)restoreCatalog();else $('browse').focus();}
$('browse').hidden=false;$('browse').onclick=()=>setBrowse(!browseOpen);$('navToggle').onclick=()=>{const expanded=document.body.classList.toggle('nav-expanded');$('navToggle').setAttribute('aria-expanded',String(expanded));};$('searchToggle').onclick=()=>{document.body.classList.toggle('show-search');if(document.body.classList.contains('show-search'))$('search').focus();else{$('search').value='';render();}};
const navPaths={'Todos':'M3 10l9-7 9 7v11h-6v-8H9v8H3z','TV':'M3 7h18v14H3z M8 2l4 5 4-5 M9 11l6 3-6 3z','Radio':'M3 8l17-5 M3 8h18v12H3z M7 13h4 M16 12v5','Deportes':'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M8 9l4-3 4 3-2 5h-4z M12 14v7 M8 9L4 7 M16 9l4-2','Música':'M9 18V5l11-2v13 M9 18a3 3 0 1 1-6 0 3 3 0 1 1 6 0 M20 16a3 3 0 1 1-6 0 3 3 0 1 1 6 0','Destacados':'M12 2l3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1z','Explorar':'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M16 8l-3 5-5 3 3-5z','Infantil':'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M8 10h.1 M16 10h.1 M8 15q4 4 8 0','Noticias':'M3 4h18v16H3z M7 8h4v4H7z M14 8h4 M14 12h4 M7 16h11','Películas':'M3 8h18v13H3z M3 8l-1-5 18-2 1 5 M7 3l4 4 M14 2l4 4','Series':'M6 3h15v14H6z M3 7v14h14 M11 7l5 3-5 3z','Documentales':'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M3 12h18 M12 3q-8 9 0 18 M12 3q8 9 0 18','Cristianos':'M3 4q5-2 9 2 4-4 9-2v15q-5-2-9 2-4-4-9-2z M12 6v15','Favoritos':'M12 21L3 12Q-1 3 7 4q3 0 5 4 2-4 5-4 8-1 4 8z'};function svgIcon(d){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${d}"/></svg>`;}
const categoryIcons={'Todos':'⌂','Radio':'♫','Deportes':'⚽','Música':'♫','Destacados':'★','Explorar':'⌕','Infantil':'☺','Noticias':'▤','TV':'▣','Películas':'▤','Series':'▥','Documentales':'◎','Cristianos':'✦','Favoritos':'♥'};for(const opt of $('filter').options){const b=document.createElement('button');b.title=opt.value;b.setAttribute('aria-label',opt.value);const i=document.createElement('span');i.innerHTML=svgIcon(navPaths[opt.value]||'M4 4h16v16H4z');i.className='category-icon';i.style.color=({'Todos':'#ffbf46','TV':'#39baff','Radio':'#ffad42','Deportes':'#52d788','Música':'#ff6585','YouTube':'#ff4242','Películas':'#36dded','Series':'#c58aff','Documentales':'#4cdbc0','Cristianos':'#ffd46b','Favoritos':'#ff6585'})[opt.value]||'#64caff';const t=document.createElement('span');t.className='nav-label';t.textContent=opt.value==='Todos'?'Inicio':opt.value;b.append(i,t);b.onclick=()=>{$('filter').value=opt.value;vodBrowse=['Películas','Series','Documentales'].includes(opt.value);$('search').value='';render();document.body.classList.remove('nav-expanded');$('navToggle').setAttribute('aria-expanded','false');};$('navRail').append(b);b.classList.toggle('active',opt.value===$('filter').value);}
document.addEventListener('keydown',e=>{if((e.key==='Escape'||e.key==='BrowserBack'||e.key==='GoBack')&&!full&&!browseOpen&&!document.querySelector('dialog[open]')){e.preventDefault();setBrowse(true);}});

function adjacent(delta){if(!selected)return null;const list=visibleChannels();const order=list.some(c=>c[2]===selected[2])?list:channelOrder;const i=order.findIndex(c=>c[2]===selected[2]);return i<0?null:order[i+delta]||null;}
function updateStepButtons(){$('prev').disabled=!adjacent(-1);$('next').disabled=!adjacent(1);}
function restoreCatalog(){requestAnimationFrame(()=>{if(!browseOpen||full)return;const list=$('list');list.scrollTop=catalogOffset;const row=[...list.children].find(r=>selected&&r.dataset.url===selected[2]);if(row){const a=row.getBoundingClientRect(),b=list.getBoundingClientRect();if(a.top<b.top||a.bottom>b.bottom)list.scrollTop+=a.top-b.top;}catalogOffset=list.scrollTop;});}
function changeChannel(delta){const c=adjacent(delta);if(c){revealControls();play(c);}}
$('prev').onclick=()=>changeChannel(-1);$('next').onclick=()=>changeChannel(1);
$('list').addEventListener('scroll',()=>{if(browseOpen&&!full)catalogOffset=$('list').scrollTop;});
document.addEventListener('keydown',e=>{if(!selected||e.target.closest('input,select,textarea,dialog'))return;if(['PageUp','ChannelUp','PageDown','ChannelDown'].includes(e.key)){e.preventDefault();changeChannel(['PageUp','ChannelUp'].includes(e.key)?1:-1);}});

function applyFormat(el){const f=localStorage.getItem('screenFormat')||'Normal';el.style.objectFit=f==='Zoom'?'cover':f==='Normal'?'contain':'fill';el.style.aspectRatio={'16:9':'16/9','4:3':'4/3','21:9':'21/9'}[f]||'auto';if(['16:9','4:3','21:9'].includes(f)){el.style.width='auto';el.style.height='100%';el.style.maxWidth='100%'}else{el.style.width='100%';el.style.height='100%'}}
const formatSelect=document.createElement('select');formatSelect.setAttribute('aria-label','Formato de pantalla');for(const f of ['Normal','Llenar pantalla','16:9','4:3','21:9','Zoom'])formatSelect.add(new Option(f,f));formatSelect.value=localStorage.getItem('screenFormat')||'Normal';formatSelect.onchange=()=>{localStorage.setItem('screenFormat',formatSelect.value);const v=$('media').querySelector('video');if(v)applyFormat(v)};$('stage-controls').append(formatSelect);

// Compact playback controls and persistent volume.
let webVolume=Math.max(0,Math.min(1,Number(localStorage.getItem('webVolume')??1)||0)),webMuted=localStorage.getItem('webMuted')==='true';
const controlPaths={prev:'M5 4v16 M19 4L8 12l11 8z',next:'M19 4v16 M5 4l11 8-11 8z',stop:'M6 6h12v12H6z',full:'M3 9V3h6 M15 3h6v6 M21 15v6h-6 M9 21H3v-6',play:'M8 4l12 8-12 8z',pause:'M8 4v16 M16 4v16',volume:'M3 9h4l5-5v16l-5-5H3z M16 8q6 4 0 8',mute:'M3 9h4l5-5v16l-5-5H3z M16 9l5 6 M21 9l-5 6',guide:'M3 5h18v16H3z M3 10h18 M8 2v6 M16 2v6'};
function decorate(b,path,label){b.innerHTML=svgIcon(controlPaths[path]);b.title=label;b.setAttribute('aria-label',label)}
for(const [id,label] of Object.entries({prev:'Canal anterior',next:'Canal siguiente',stop:'Detener',full:'Pantalla completa'}))decorate($(id),id,label);decorate(guideButton,'guide','Programación TV');
const playButton=document.createElement('button');decorate(playButton,'play','Reproducir / pausar');$('prev').after(playButton);playButton.onclick=()=>{const el=$('media').querySelector('audio,video');if(el){if(el.paused)el.play().catch(()=>{});else el.pause();}};
for(const ev of ['play','pause','ended'])$('media').addEventListener(ev,()=>{const el=$('media').querySelector('audio,video');decorate(playButton,el&&!el.paused?'pause':'play',el&&!el.paused?'Pausar':'Reproducir');},true);
const volumeRow=document.createElement('div');volumeRow.id='volumeRow';const muteButton=document.createElement('button'),volumeInput=document.createElement('input'),volumeOutput=document.createElement('output');volumeInput.type='range';volumeInput.min='0';volumeInput.max='100';volumeInput.setAttribute('aria-label','Volumen');volumeRow.append(muteButton,volumeInput,volumeOutput);$('stage-controls').append(volumeRow);
function syncVolume(){volumeInput.value=String(Math.round(webVolume*100));volumeOutput.textContent=webMuted?'0%':volumeInput.value+'%';decorate(muteButton,webMuted||webVolume===0?'mute':'volume',webMuted?'Restaurar sonido':'Silenciar');localStorage.setItem('webVolume',String(webVolume));localStorage.setItem('webMuted',String(webMuted));}
function applyVolume(){const el=$('media').querySelector('audio,video');if(el){el.volume=webVolume;el.muted=webMuted;}syncVolume();}volumeInput.oninput=()=>{webVolume=Number(volumeInput.value)/100;webMuted=false;applyVolume()};muteButton.onclick=()=>{webMuted=!webMuted;applyVolume()};syncVolume();

