try{const last=localStorage.getItem('lastChannel127'),key=localStorage.getItem('lastStation127');const c=channels.find(x=>x[2]===last)||channels.find(x=>numberKey(x)===key)||channels.find(x=>x[0]==='RMRC Radio');if(c)play(c);}catch(e){console.warn('No se pudo recuperar canal',e);}
let digits127='',digitsTimer127;document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,dialog')||!/^\d$/.test(e.key))return;e.preventDefault();digits127+=e.key;clearTimeout(digitsTimer127);digitsTimer127=setTimeout(()=>{const n=Number(digits127);digits127='';if(['Películas','Series','Documentales'].includes($('filter').value))return;const c=visibleChannels(true)[n-1];if(c)play(c)},900)});

async function refreshVodCatalog(){try{const r=await fetch('vod_catalog.json',{cache:'no-cache'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(d.schema!==1||!Array.isArray(d.items))throw Error('Catálogo incompatible');const fresh=d.items.filter(m=>['Películas','Series','Documentales'].includes(m.type)&&m.source&&m.license&&m.url.startsWith('https://')&&onDemand([m.name,m.type,m.url]));if(!fresh.length)return;mergeVod(fresh);render();}catch(e){console.warn('Videoteca',e)}}
refreshVodCatalog();

$('backVod').onclick=()=>{vodBrowse=true;setBrowse(true);render()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!full&&!vodBrowse&&['Películas','Series','Documentales'].includes($('filter').value)&&!document.querySelector('dialog[open]')){e.preventDefault();$('backVod').click()}});

function platform134(){const ua=navigator.userAgent;if(/iPad/i.test(ua)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)return 'iPadOS';if(/iPhone|iPod/i.test(ua))return 'iOS';if(/Android/i.test(ua))return /TV|AFT|BRAVIA/i.test(ua)?'Android TV':'Android';if(/Windows/i.test(ua))return 'Windows';return 'Web';}
$('about134').onclick=()=>{$('aboutPlatform134').textContent='1.2.14 · '+platform134()+' (Web)';$('aboutDialog134').showModal()};
$('feedback134').onclick=()=>$('feedbackDialog134').showModal();
$('feedbackForm134').onsubmit=e=>{e.preventDefault();const msg=$('feedbackText134').value.trim();if(!msg)return;const text=`CENTROTV-CR 1.2.14 · ${platform134()} (Web)\n${$('feedbackKind134').value} · ${$('feedbackRating134').value}/5\n${msg}`;window.location.href='mailto:ucampoca@gmail.com?subject='+encodeURIComponent('Feedback CENTROTV-CR')+'&body='+encodeURIComponent(text);$('feedbackDialog134').close();};

